mapper.select:
SELECT r.artifact_ref
FROM ebus_generation_run r
INNER JOIN ebus_artifact a ON a.biz_id = r.artifact_ref AND a.user_id = r.user_id
WHERE r.user_id = #{userId}
  AND r.session_id = #{sessionId}
  AND r.artifact_ref IS NOT NULL
  AND r.artifact_ref <> ''


      AND a.artifact_type = #{artifactType}


      AND a.artifact_type IN ('picklist', 'sku')


  AND a.created_at >= #{since}
ORDER BY r.created_at DESC
LIMIT 1
